  "scam_type": "Digital Arrest Scam",
  "red_flags": [
    {
      "phrase": "This is CBI Officer Sharma",
      "tag": "IMPERSONATION",
      "why": "Scammers often pose as law enforcement agencies like the CBI to scare victims."
    },
    {
      "phrase": "A parcel booked in your name contains illegal items",
      "tag": "FEAR TACTICS",
      "why": "False allegations regarding illegal parcels are a common tactic used to create panic."
    },
    {
      "phrase": "You are under digital arrest",
      "tag": "IMPERSONATION",
      "why": "'Digital arrest' is a complete fake concept used exclusively by scammers; law enforcement does not arrest people over video calls."
    },
    {
      "phrase": "Stay on this video call and do not tell anyone",
      "tag": "ISOLATION",
      "why": "Scammers force you to stay on a video call and isolate you so you cannot verify the truth or ask for help."
    }
  ],
  "explanation": "This is a severe scam known as a 'digital arrest' fraud. Scammers pretend to be police or CBI officers, claim you are involved in a crime, and threaten you over video calls to extort money. Real law enforcement agencies never conduct arrests or interrogations over video calls.",
  "next_steps": [
    "Disconnect the video call immediately and do not follow any instructions.",
    "Do not transfer any money or share personal details.",
    "Block the caller's number.",
    "Report the incident to the National Cyber Crime Reporting Portal at cybercrime.gov.in or call 1930."
  ]
}
